SELECT CASE WHEN YEAR(hire_date) < 2024 THEN 'before_2024' WHEN YEAR(hire_date) = 2024 THEN '2024' ELSE 'after_2024' END AS hire_cohort, job_title, SORT_ARRAY(COLLECT_SET(level)) AS level_list FROM employees WHERE email LIKE '%@mail.co.th' AND (is_remote = TRUE OR full_name IS NOT NULL) GROUP BY ROLLUP(CASE WHEN YEAR(hire_date) < 2024 THEN 'before_2024' WHEN YEAR(hire_date) = 2024 THEN '2024' ELSE 'after_2024' END, job_title) ORDER BY hire_cohort, job_title DESC;
